def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    giraffe_patches = image_patch.find("giraffe")
    if not giraffe_patches: return image_patch

    giraffe = giraffe_patches[0]

    # Find all objects that might be in front of the giraffe
    objects_in_front = []
    for obj_name in ["tree", "building", "house"]:
        obj_patches = image_patch.find(obj_name)
        for obj_patch in obj_patches:
            if giraffe.overlaps_with(*obj_patch.bbox()):
                objects_in_front.append((obj_patch, obj_patch.compute_depth()))

    if not objects_in_front: return giraffe

    # Sort objects in front by depth
    objects_in_front.sort(key=lambda x: x[1])

    # Check if the giraffe is looking down at any of these objects
    for obj_patch, _ in objects_in_front:
        if giraffe.vertical_center < obj_patch.vertical_center:
            return obj_patch

    return giraffe

