    if giraffe_distance <= first_giraffe.width / 2 + second_giraffe.width / 2:
        giraffes_in_contact = [first_giraffe, second_giraffe]

        head_over_railing_patches = []
        for giraffe in giraffes_in_contact:
            head_patches = giraffe.find("head")
            for head in head_patches:
                if head.overlaps_with(*second_giraffe.bbox):
                    head_over_railing_patches.append(head)

        if head_over_railing_patches:
            return min(head_over_railing_patches, key=lambda h: h.vertical_center)

    return image_patch

